SELECT p.status,p.total_amount,
 (SELECT CAST(SUM(r.base_quantity*r.base_unit_cost) AS DECIMAL(14,2)) FROM inventory_receipt_batch r JOIN inventory_receipt_line l ON l.id=r.receipt_line_id JOIN inventory_receipt h ON h.id=l.receipt_id WHERE h.purchase_order_id=1)
 FROM purchase_order p WHERE p.id=1;

SELECT COUNT(*) FROM inventory_movement m WHERE
 (m.to_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_batch_balance b WHERE b.batch_id=m.batch_id AND b.store_id=m.store_id AND b.location_id=m.to_location_id))
 OR (m.from_location_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_batch_balance b WHERE b.batch_id=m.batch_id AND b.store_id=m.store_id AND b.location_id=m.from_location_id));
